 bool SpaceInteractionInput(MouseState m,KeyboardState keys,float dt){if(world.Docked||world.Screen!=ViewMode.Space)return false;if(WindowAt(mouse)?.Kind==ViewMode.SolarMap&&m.ScrollWheelValue!=oldMouse.ScrollWheelValue){solarMapZoom=Math.Clamp(solarMapZoom*MathF.Pow(1.25f,(m.ScrollWheelValue-oldMouse.ScrollWheelValue)/120),1,512);return true;}if(trackingCamera&&world.Selected!=null)renderer.LookAtTarget=true;
